import {
    Mesh,
    PlaneGeometry,
    MeshBasicNodeMaterial,
    Texture,
    Object3D
} from 'three/webgpu';
import { gsap, TimelineLite } from 'gsap';
import { Vector3 } from 'three/webgpu';
import { NodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
    // ----- Geometry & Texture -----
    const imgUrl = config.assets?.imageUrl ?? '';
    /** @type {Texture} */
    const texture = ctx.textureLoader(imgUrl);
    // Assume image rect defines aspect ratio 512:320 = 1.6
    const aspect = 512 / 320;
    const width = 1.6; // scene‑units, arbitrary base width
    const height = width / aspect;

    const geometry = new PlaneGeometry(width, height);
    const material = new MeshBasicNodeMaterial({
        map: texture,
        // ensure transparent if texture has alpha
        transparent: true
    });

    const mesh = new Mesh(geometry, material);
    mesh.name = config.id ?? 'quote-panel';

    // ----- Transform -----
    const pos = config.position ?? { x: 0, y: 0, z: 0 };
    mesh.position.set(pos.x, pos.y, pos.z);
    const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
    mesh.rotation.set(rot.x, rot.y, rot.z);
    const scl = config.scale ?? { x: 1, y: 1, z: 1 };
    mesh.scale.set(scl.x, scl.y, scl.z);

    // ----- Cinematic Primitives -----
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach((prim) => {
            const fn = ctx.primitives?.[prim.name];
            if (typeof fn === 'function') {
                fn(mesh, prim.params ?? {});
            }
        });
    }

    // ----- Interaction Handlers -----
    const originalY = mesh.position.y;
    const hoverTimeline = gsap.timeline({ paused: true });
    hoverTimeline.to(mesh.position, {
        y: originalY + 0.15,
        ease: 'power3.out',
        duration: 0.7
    });

    const pressTimeline = gsap.timeline({ paused: true });
    pressTimeline
        .to(mesh.scale, {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            ease: 'back.out(1.7)',
            duration: 0.12
        })
        .to(mesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            ease: 'back.out(1.7)',
            duration: 0.12
        });

    mesh.userData.handlers = {
        hoverEnter: () => {
            hoverTimeline.play();
        },
        hoverLeave: () => {
            hoverTimeline.reverse();
        },
        click: () => {
            // Emit event via context if available
            if (typeof ctx.emit === 'function') {
                ctx.emit('hub-pricing.select');
            }
            pressTimeline.restart();
        }
    };

    // ----- Cleanup -----
    mesh.userData.cleanup = () => {
        geometry.dispose();
        material.dispose();
        if (texture && texture.dispose) texture.dispose();
        hoverTimeline.kill();
        pressTimeline.kill();
    };

    // Return as Object3D (mesh is already an Object3D)
    return mesh;
}
